"use client";

import { useRef } from "react";
import { Section } from "@/components/ui/Section";
import { Heading } from "@/components/ui/Reveal";
import { Button } from "@/components/ui/Button";
import { gsap, useIsomorphicLayoutEffect, EASE } from "@/lib/gsap";
import { useAppStore } from "@/store/useAppStore";
import { COMPANY } from "@/data/company";
import { scrimStop } from "@/components/ui/Overlays";

export function Hero() {
  const entered = useAppStore((s) => s.entered);
  const root = useRef<HTMLDivElement>(null);

  useIsomorphicLayoutEffect(() => {
    if (!entered || !root.current) return;

    const ctx = gsap.context(() => {
      const tl = gsap.timeline({ delay: 0.25 });

      tl.fromTo(
        "[data-hero-eyebrow]",
        { y: 20, opacity: 0 },
        { y: 0, opacity: 1, duration: 1, ease: EASE.expo },
      )
        .fromTo(
          "[data-hero-lede]",
          { y: 24, opacity: 0 },
          { y: 0, opacity: 1, duration: 1.1, ease: EASE.expo },
          0.95,
        )
        .fromTo(
          "[data-hero-cta] > *",
          { y: 22, opacity: 0 },
          { y: 0, opacity: 1, duration: 1, ease: EASE.expo, stagger: 0.08 },
          1.1,
        )
        .fromTo(
          "[data-hero-foot]",
          { y: 16, opacity: 0 },
          { y: 0, opacity: 1, duration: 1, ease: EASE.expo },
          1.25,
        );

      // The whole hero drifts up and dims as the journey starts moving.
      gsap.to("[data-hero-inner]", {
        yPercent: -14,
        opacity: 0,
        ease: "none",
        scrollTrigger: {
          trigger: root.current,
          start: "top top",
          end: "bottom top",
          scrub: 0.6,
        },
      });
    }, root);

    return () => ctx.revert();
  }, [entered]);

  return (
    <Section id="hero" className="h-[100svh] min-h-[640px]" label="Introduction">
      <div ref={root} className="absolute inset-0">
        {/* Scrim: the core sits directly behind the headline, so the type needs
            a little ground of its own to hold contrast against. */}
        <div
          aria-hidden
          className="pointer-events-none absolute inset-0"
          style={{
            background:
              `radial-gradient(62% 48% at 50% 52%, ${scrimStop(0.88, 0.5)} 0%,` +
              ` ${scrimStop(0.6, 0.55)} 46%, ${scrimStop(0.18, 0.7)} 78%,` +
              ` ${scrimStop(0, 0)} 100%)`,
          }}
        />

        <div
          data-hero-inner
          className="shell relative flex h-full flex-col items-center justify-center pt-24 text-center"
        >
          <div data-hero-eyebrow className="mb-8 flex items-center gap-3 opacity-0">
            <span className="relative flex h-1.5 w-1.5">
              <span className="absolute inset-0 animate-ping rounded-full bg-ion opacity-75" />
              <span className="relative h-1.5 w-1.5 rounded-full bg-ion" />
            </span>
            <span className="eyebrow whitespace-nowrap text-fog text-shadow-scrim">
              {COMPANY.descriptor}
              <span className="hidden sm:inline"> — Founded {COMPANY.founded}</span>
            </span>
          </div>

          <Heading
            as="h1"
            immediate
            play={entered}
            delay={0.35}
            className="display-xl font-display font-medium text-chalk"
            lines={[
              <>We Build Digital</>,
              <>
                Products That{" "}
                <span className="serif-accent text-ion">Move</span>
              </>,
              <>Businesses Forward</>,
              <>And Markets Ahead</>,
            ]}
          />

          <p
            data-hero-lede
            className="lede mt-8 max-w-[54ch] text-balance text-fog opacity-0 text-shadow-scrim"
          >
            We design and develop high-performance websites, custom software,
            mobile apps, and digital experiences built to scale.
          </p>

          <div
            data-hero-cta
            className="mt-11 flex flex-col items-center gap-3 sm:flex-row"
          >
            <div className="opacity-0">
              <Button href="#cta" variant="primary" size="lg">
                Start a Project
              </Button>
            </div>
            <div className="opacity-0">
              <Button href="#work" variant="ghost" size="lg">
                Explore Our Work
              </Button>
            </div>
          </div>
        </div>

        <div
          data-hero-foot
          className="shell pointer-events-none absolute inset-x-0 bottom-6 flex items-end justify-between opacity-0 md:bottom-9"
        >
          <div className="flex items-center gap-3">
            <span className="relative block h-9 w-px overflow-hidden bg-hairline-strong">
              <span className="absolute inset-x-0 top-0 h-3 animate-[scrollcue_2.2s_ease-in-out_infinite] bg-ion" />
            </span>
            <span className="eyebrow">Scroll</span>
          </div>

          <div className="hidden gap-8 sm:flex">
            {COMPANY.locations.map((city) => (
              <span key={city} className="eyebrow">
                {city}
              </span>
            ))}
          </div>
        </div>
      </div>
    </Section>
  );
}
