"use client";

import { useEffect } from "react";
import { journey } from "@/lib/journey";
import { applyTheme, themeAt } from "@/lib/theme";
import { useAppStore } from "@/store/useAppStore";

/**
 * Writes the themed CSS custom properties on <html> as the journey advances.
 *
 * Runs on its own rAF loop outside React and only writes when the value has
 * moved meaningfully — outside a transition that is zero style recalculations,
 * and during one it is a few dozen spread over the whole crossover.
 */
export function ThemeDriver() {
  const webgl = useAppStore((s) => s.webgl);

  useEffect(() => {
    const root = document.documentElement;

    // The static fallback is a single flat backdrop, so pin the environment
    // to the page's default rather than letting tokens drift against it.
    if (!webgl) {
      applyTheme(1, root);
      return;
    }

    let raf = 0;
    let last = -1;

    const tick = () => {
      const t = themeAt(journey.stage);
      if (Math.abs(t - last) > 0.006) {
        last = t;
        applyTheme(t, root);
      }
      raf = requestAnimationFrame(tick);
    };

    applyTheme(themeAt(journey.stage), root);
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [webgl]);

  return null;
}
